// Mastodon logo + student initials ROM — 176×128 pixels, 4-color palette.
//
// Layout (columns, left to right):
//   x =   0..127 : Mastodon mascot (128×128, upsampled from 64×64 source)
//   x = 128..129 : grey vertical separator
//   x = 130..175 : text panel (46 px wide)
//
// Text panel row layout (y = 0..127):
//   y =   0       : top padding
//   y =   1..  8  : C.A
//   y =  10.. 17  : B.F
//   y =  19.. 26  : A.V
//   y =  28.. 35  : V.V
//   y =  37.. 44  : H.M
//   y =  46.. 53  : E.O
//   y =  55.. 62  : E.R
//   y =  64.. 71  : S.Q
//   y =  73.. 80  : S.N
//   y =  82.. 89  : M.H
//   y =  91.. 98  : A.W
//   y = 100..107  : G.W
//   y = 109..110  : grey horizontal separator
//   y = 111..117  : PFW  (orange)
//   y = 120..126  : ECE  (orange)
//
// Effective VGA output: R[1:0]=pixel[7:6]  G[1:0]=pixel[5:4]  B[1:0]=pixel[3:2]
//
// Palette:
//   idx 0: 8'hFC  white   (default — background)
//   idx 1: 8'h00  black   (mastodon outline + initials text)
//   idx 2: 8'hA8  grey    (separators + mastodon body)
//   idx 3: 8'hE0  orange  ('PFW ECE' text + mastodon accent)
//
// Address: {y[6:0], x[7:0]} — 15-bit, row-major.
// Mastodon color accuracy: 84.8% exact effective-VGA-color match.
`default_nettype none

module mastodon_rom_compress (
    input  wire [7:0] x,
    input  wire [6:0] y,
    output reg  [7:0] pixel
);

    reg [1:0] idx;

    always @(*) begin
        case ({y, x})
